def min_window_subsequence(s1, s2):
    m, n = len(s1), len(s2)
    dp = [-1] * n
    result = ""
    min_len = float('inf')

    for i in range(m):
        # Reverse to preserve dp[j-1]
        for j in range(n - 1, -1, -1):
            if s1[i] == s2[j]:
                dp[j] = i if j == 0 else dp[j - 1]

        if dp[n - 1] != -1:
            start = dp[n - 1]
            length = i - start + 1
            if length < min_len:
                min_len = length
                result = s1[start:i + 1]

    return result
